  1150                          ((uint64_t) (y / decc->y_samples) *
  1151                           (uint64_t) decc->user_line_stride);
  1152                  else
  1153                  {
  1154                      srcbuffer += w * bpc;
  1155                      continue;
  1156                  }
  1157              }
  1158              else if (cdata)
  1159              {
  1160                  cdata += ((uint64_t) y) * ((uint64_t) decc->user_line_stride);
  1161              }
  1162              else
  1163              {
  1164                  srcbuffer += w * bpc;
